  const EXTRA = [['gaps', 'Missing requirements check'], ['workshop', 'Workshop intelligence'], ['pkg', 'Org package analysis'], ['wsr', 'Weekly status report'], ['monthly', 'Monthly report'], ['calendar', 'Calendar briefing'], ['govupdate', 'Weekly update to the customer'], ['dashsummary', 'Dashboard report summary'], ['ftrrows', 'FTR scenario suggestions'], ['vidguide', 'Guide steps from a walkthrough']];
  const label = t => (DELIV.concat(EXTRA.map(x => [x[0], x[1]])).find(d => d[0] === t) || [0, t])[1];
  const drafts = () => I().list('ai').sort((a, b) => (b._created || '').localeCompare(a._created || ''));
